from hwlib import M, P, part, SET

K = r"k = \frac{1}{4\pi\varepsilon_0}"

HW01 = SET("hw01", "HW01 · Ch 21 Coulomb's Law", "CST homework01 (Chapter 21), mxhuang@scut.edu.cn", [
  M(1, "A conductor is distinguished from an insulator with the same number of atoms by the number of:",
    ["nearly free atoms", "electrons", "nearly free electrons", "protons", "molecules"], "C",
    "What makes a material a conductor is having electrons that can move freely. Both have the same atoms (and so the same electrons and protons); the conductor just has many *nearly free* electrons."),
  M(2, "A small object has charge $Q$. Charge $q$ is removed from it and placed on a second small object. The two objects are placed 1 m apart. For the force that each object exerts on the other to be a maximum, $q$ should be:",
    ["$2Q$", "$Q$", "$Q/2$", "$Q/4$", "$0$"], "C",
    r"$F \propto (Q-q)\,q$. This product is largest when the charge is split evenly: $\frac{dF}{dq} \propto Q - 2q = 0 \Rightarrow q = Q/2$.",
    r"""The two charges are $Q-q$ and $q$, so $$F = k\frac{(Q-q)\,q}{r^2}.$$ With $r$ fixed, maximize $f(q) = (Q-q)q = Qq - q^2$: $$\frac{df}{dq} = Q - 2q = 0 \;\Rightarrow\; q = \frac{Q}{2}.$$ **Why this method:** "maximum" means set the derivative to zero. (It's a downward parabola, so this is a maximum.)"""),
  M(3, "Two small charged objects repel each other with a force $F$ when separated by a distance $d$. If the charge on each object is reduced to one-fourth of its original value and the distance between them is reduced to $d/2$, the force becomes:",
    ["$F/16$", "$F/8$", "$F/4$", "$F/2$", "$F$"], "C",
    r"$F \propto q_1q_2/r^2$: the charges give $\frac14\cdot\frac14 = \frac1{16}$, halving $r$ gives $\times 4$. Total $\frac{4}{16}F = F/4$.",
    r"""$$F' = k\frac{(q_1/4)(q_2/4)}{(d/2)^2} = \frac{1/16}{1/4}\,k\frac{q_1q_2}{d^2} = \frac{F}{4}.$$ **Why this method:** use ratios. You never need the actual charges; just track how each factor in Coulomb's law changes."""),
  M(4, "A 5.0-C charge is 10 m from a −2.0 C charge. The electrostatic force on the positive charge is:",
    [r"$9.0\times10^{8}$ N toward the negative charge", r"$9.0\times10^{8}$ N away from the negative charge",
     r"$9.0\times10^{9}$ N toward the negative charge", r"$9.0\times10^{9}$ N away from the negative charge", "none of these"], "A",
    r"$F = k\frac{|q_1q_2|}{r^2} = (9\times10^9)\frac{(5)(2)}{10^2} = 9.0\times10^{8}$ N. Opposite signs attract, so it points toward the negative charge."),
  M(5, "A particle with charge $Q$ is on the $y$ axis a distance $a$ from the origin and a particle with charge $q$ is on the $x$ axis a distance $d$ from the origin. The value of $d$ for which the $x$ component of the force on the second particle is the greatest is:",
    ["$0$", "$a$", r"$\sqrt2\,a$", "$a/2$", r"$a/\sqrt2$"], "E",
    r"$F_x = k\frac{Qq}{d^2+a^2}\cos\theta = kQq\frac{d}{(d^2+a^2)^{3/2}}$. Setting $dF_x/dd = 0$ gives $a^2 = 2d^2$, so $d = a/\sqrt2$.",
    r"""The distance is $\sqrt{d^2+a^2}$ and $\cos\theta = d/\sqrt{d^2+a^2}$, so $$F_x = kQq\,\frac{d}{(d^2+a^2)^{3/2}}.$$ Differentiate: $$\frac{d}{dd}\left[\frac{d}{(d^2+a^2)^{3/2}}\right] = \frac{(d^2+a^2) - 3d^2}{(d^2+a^2)^{5/2}} = 0 \;\Rightarrow\; a^2 = 2d^2 \;\Rightarrow\; d = \frac{a}{\sqrt2}.$$ **Why this method:** at $d = 0$ the force is all vertical ($F_x = 0$), and far away the force is tiny, so there's a maximum in between; calculus finds it."""),
  M(6, r"A particle with a charge of $5.0\times10^{-6}$ C and a mass of 20 g moves uniformly with a speed of 7 m/s in a circular orbit around a stationary particle with a charge of $-5.0\times10^{-6}$ C. The radius of the orbit is:",
    ["0 m", "0.23 m", "0.62 m", "1.6 m", "4.4 m"], "B",
    r"The electric attraction is the centripetal force: $k\frac{Qq}{r^2} = \frac{mv^2}{r} \Rightarrow r = \frac{kQq}{mv^2} = \frac{(9\times10^9)(25\times10^{-12})}{(0.020)(49)} = 0.23$ m."),
  M(7, "Two protons ($p_1$ and $p_2$) and an electron ($e$) lie on a straight line, as shown. The directions of the force of $p_1$ on $e$, the force of $p_2$ on $e$, and the total force on $e$, respectively, are:",
    ["(see figure)", "(see figure)", "(see figure)", "(see figure)", "(see figure)"], "D",
    "Each proton pulls the electron toward itself (opposite charges attract). The total force points toward the CLOSER proton, because Coulomb's force grows as $1/r^2$.",
    nofig=True, note="The answer arrows and the figure were images in the original file; official answer D."),
  M(8, "Particle 1 with charge $q_1$ and particle 2 with charge $q_2$ are on the $x$ axis, with particle 1 at $x = a$ and particle 2 at $x = -2a$. For the net force on a third charged particle at the origin to be zero, $q_1$ and $q_2$ must be related by $q_2 =$",
    ["$2q_1$", "$4q_1$", "$-2q_1$", "$-4q_1$", "$-q_1/4$"], "B",
    r"The two forces must point in opposite directions, so $q_1$ and $q_2$ have the SAME sign, and be equal in size: $\frac{q_1}{a^2} = \frac{q_2}{(2a)^2} \Rightarrow q_2 = 4q_1$."),
  M(9, r"A particle with charge 2 μC is placed at the origin. An identical particle is placed 2 m from the origin on the $x$ axis, and a third identical particle 2 m from the origin on the $y$ axis. The magnitude of the force on the particle at the origin is:",
    [r"$9.0\times10^{-3}$ N", r"$6.4\times10^{-3}$ N", r"$1.3\times10^{-2}$ N", r"$1.8\times10^{-2}$ N", r"$3.6\times10^{-2}$ N"], "C",
    r"Each neighbour pushes with $F = k\frac{(2\times10^{-6})^2}{2^2} = 9.0\times10^{-3}$ N, one along $-x$ and one along $-y$. At right angles they add to $\sqrt2\,F = 1.3\times10^{-2}$ N."),
  M(10, "Two particles, each with charge $Q$, and a third particle with charge $q$ are placed at the vertices of an equilateral triangle as shown. The total force on the particle with charge $q$ is:",
    ["parallel to the left side of the triangle", "parallel to the right side of the triangle", "parallel to the bottom side of the triangle",
     "perpendicular to the bottom side of the triangle", "perpendicular to the left side of the triangle"], "D",
    "The two equal charges $Q$ sit symmetrically about the vertical line through $q$. Their sideways components cancel and the vertical ones add, so the total force is perpendicular to the bottom side.",
    nofig=True),
  M(11, "Charge is distributed uniformly on the surface of a spherical nonconducting shell. A point particle with charge $q$ is inside. The electrical force on the particle $q$ is least when:",
    ["it is near the inside surface of the shell", "it is at the center of the shell", "it is halfway between the shell center and the inside surface",
     "it is near, but not at, the center of the shell", "all of the above (the force is zero everywhere inside)"], "E",
    "Shell theorem: a uniformly charged shell exerts NO net force on a charge anywhere inside it, so the force is zero (and equally 'least') at every point."),
  M(12, "Two uncharged metal spheres, L and M, are in contact. A negatively charged rod is brought close to L, but not touching it, as shown. The two spheres are slightly separated and the rod is then withdrawn. As a result:",
    ["both spheres are neutral", "both spheres are positive", "both spheres are negative", "L is negative and M is positive", "L is positive and M is negative"], "E",
    "The negative rod pushes free electrons from L over to M. Separating the spheres traps that imbalance: L (near the rod) ends up positive and M negative. This is charging by induction.",
    nofig=True),
  M(13, "Two identical conducting spheres A and B carry equal charge and exert electrostatic forces of magnitude $F$ on each other. A third identical, uncharged conducting sphere C is first touched to A, then to B, and finally removed. The force between A and B becomes:",
    ["$F/2$", "$F/4$", "$3F/8$", "$F/16$", "$0$"], "C",
    r"Identical conductors share charge equally. C + A: each gets $q/2$. C + B: $(q/2 + q)/2 = 3q/4$ each. New force $\propto \frac{q}{2}\cdot\frac{3q}{4} = \frac38 q^2$, so $F' = 3F/8$."),
  M(14, "Which of the following is NOT a possible value for the electric charge on an object?",
    [r"$8.0\times10^{-20}$ C", r"$8.0\times10^{-19}$ C", r"$8.0\times10^{-18}$ C", r"$8.0\times10^{-17}$ C", r"$8.0\times10^{-16}$ C"], "A",
    r"Charge comes in whole multiples of $e = 1.6\times10^{-19}$ C. $8.0\times10^{-20}$ C $= 0.5e$, which is impossible; the others are $5e$, $50e$, $500e$, $5000e$."),
  M(15, "In positron emission tomography, a positron interacts with an atomic electron, emitting gamma rays that are detected by the imager. This gamma ray emission process is called:",
    ["pair production", "annihilation", "absorption", "alpha decay", "fission"], "B",
    r"$e^- + e^+ \to \gamma + \gamma$ is annihilation (total charge $-e + e = 0$ before and after). Pair production is the reverse, $\gamma \to e^- + e^+$."),
  M(16, r"A particle ($m = 50$ g, $q = 5.0$ μC) is released from rest when it is 50 cm from a second particle ($Q = -20.0$ μC). Determine the magnitude of the initial acceleration of the 50 g particle.",
    [r"54 m/s$^2$", r"90 m/s$^2$", r"72 m/s$^2$", r"65 m/s$^2$", r"36 m/s$^2$"], "C",
    r"$F = k\frac{|qQ|}{r^2} = (9\times10^9)\frac{(5\times10^{-6})(20\times10^{-6})}{0.5^2} = 3.6$ N, then $a = F/m = 3.6/0.050 = 72$ m/s$^2$."),
  M(17, r"Identical point charges $Q$ are placed at each of the four corners of a 3.0 m × 4.0 m rectangle. If $Q = 40$ μC, what is the magnitude of the electrostatic force on any one of the charges?",
    ["3.0 N", "2.4 N", "1.8 N", "3.7 N", "2.0 N"], "B",
    r"Three neighbours push the chosen charge: along the 3 m side, along the 4 m side, and along the 5 m diagonal. Add components: $F_x = kQ^2\left(\frac1{3^2} + \frac1{5^2}\cdot\frac35\right)$, $F_y = kQ^2\left(\frac1{4^2} + \frac1{5^2}\cdot\frac45\right)$, $|F| \approx 2.4$ N.",
    r"""With $kQ^2 = (9\times10^9)(40\times10^{-6})^2 = 14.4$ N·m², take the charge at the origin with neighbours at $(3,0)$, $(0,4)$ and $(3,4)$. All forces are repulsive (pointing away), so in magnitude: $$F_x = 14.4\left(\frac{1}{9} + \frac{1}{25}\cdot\frac{3}{5}\right) = 1.947\ \text{N},\qquad F_y = 14.4\left(\frac{1}{16} + \frac{1}{25}\cdot\frac{4}{5}\right) = 1.361\ \text{N},$$ $$|F| = \sqrt{1.947^2 + 1.361^2} = 2.4\ \text{N}.$$ **Why this method:** superposition. Each pair force comes from Coulomb's law, and the diagonal one is split with $\cos\theta = 3/5$, $\sin\theta = 4/5$."""),
  M(18, r"The symbol $\frac{1}{4\pi\varepsilon_0}$ appears in Coulomb's law because we use independently defined units for:",
    ["force and distance", "charge and distance", "distance and force", "force, distance and electric charge", "charge"], "D",
    r"Newtons, metres and coulombs are each defined on their own, so a constant is needed to make $F = (\text{const})\,q_1q_2/r^2$ come out right. That constant is $1/(4\pi\varepsilon_0)$."),
  M(19, r"A point charge $Q$ is at the origin and a second charge $2Q$ is on the $x$ axis at $x = -3.0$ m. If $Q = 50$ μC, what is the magnitude of the electrostatic force on a third point charge $-Q$ placed on the $y$ axis at $y = +4.0$ m?",
    ["2.5 N", "3.0 N", "3.7 N", "4.4 N", "1.8 N"], "B",
    r"Both forces on $-Q$ are attractive. From $Q$ (4 m away): $kQ^2/16$, straight down. From $2Q$ (5 m away): $2kQ^2/25$, toward $(-3,0)$, i.e. with components $(-\frac35, -\frac45)$. Adding gives $|F| \approx 3.0$ N.",
    r"""$kQ^2 = (9\times10^9)(50\times10^{-6})^2 = 22.5$ N·m². $$F_x = -\frac{2(22.5)}{25}\cdot\frac35 = -1.08\ \text{N},\qquad F_y = -\frac{22.5}{16} - \frac{2(22.5)}{25}\cdot\frac45 = -2.85\ \text{N},$$ $$|F| = \sqrt{1.08^2 + 2.85^2} = 3.0\ \text{N}.$$ **Why this method:** vector superposition. The 3-4-5 triangle gives the direction cosines for free."""),
  M(20, r"Two small non-conducting spheres are both charged positively, the combined charge being 40 μC. When the two spheres are 50 cm apart, each is repelled from the other by a force of 2.0 N. Determine the magnitude of the smaller of the two charges.",
    ["1.4 μC", "1.1 μC", "2.0 μC", "3.3 μC", "17 μC"], "A",
    r"Let the charges be $x$ and $40\,\mu\text{C} - x$: $k\frac{x(40\times10^{-6}-x)}{0.5^2} = 2.0$. Solving the quadratic, the smaller root is $x \approx 1.4$ μC.",
    r"""$$x(40\times10^{-6} - x) = \frac{(2.0)(0.25)}{9\times10^9} = 5.56\times10^{-11}$$ $$x^2 - (40\times10^{-6})x + 5.56\times10^{-11} = 0 \;\Rightarrow\; x = \frac{40\times10^{-6} \pm \sqrt{1.6\times10^{-9} - 2.22\times10^{-10}}}{2}.$$ The two roots, 1.4 μC and 38.6 μC, are the two charges; the smaller is **1.4 μC**. **Why this method:** two unknowns, two facts (their sum and the force), so substitute and solve the quadratic."""),
  P(21, "Problem 1. Three charges A, B and C are arranged as shown in the figure. Rank the charges in order of increasing magnitude of the net force $F_A$, $F_B$, $F_C$ they experience. Indicate ties where appropriate.",
    [part("", "", r"$C < A < B$",
      r"""From the official solution (charges of size $q$, neighbouring spacing $d$): $$F_A = k\frac{q^2}{d^2} + k\frac{q^2}{(2d)^2} = \frac54\,k\frac{q^2}{d^2},\quad |F_B| = 2k\frac{q^2}{d^2},\quad F_C = -k\frac{q^2}{(2d)^2} + k\frac{q^2}{d^2} = \frac34\,k\frac{q^2}{d^2}.$$ So $\frac34 < \frac54 < 2$: **C < A < B**.""",
      "Superposition along a line: add the two Coulomb forces with signs (same direction adds, opposite directions subtract).")],
    nofig=True),
  P(22, r"Problem 2. A charge $q_1 = -6.50$ μC is at the origin, and $q_2 = -2.42$ μC is on the $x$ axis at $x = 1.00$ m. Find the net force on $q_3 = +1.40$ μC located at $x = 0.55$ m. ($k = 9.0\times10^9$ N·m²/C²)",
    [part("", "", r"$\vec F_3 = -0.12\ \text{N}\,\hat\imath$",
      r"""$q_3$ is attracted toward both negative charges. Toward $q_1$ (to the left): $$F_{31} = k\frac{|q_1q_3|}{0.55^2} = (9\times10^9)\frac{(6.50\times10^{-6})(1.40\times10^{-6})}{0.3025} = 0.27\ \text{N}\ (-\hat\imath).$$ Toward $q_2$ (to the right, 0.45 m away): $$F_{32} = (9\times10^9)\frac{(2.42\times10^{-6})(1.40\times10^{-6})}{0.2025} = 0.15\ \text{N}\ (+\hat\imath).$$ Net: $-0.27 + 0.15 = -0.12$ N, i.e. **0.12 N toward $-x$**.""",
      "1-D superposition: give each force a sign from its direction, then add.")]),
  P(23, r"Problem 3. With the same $q_1 = -6.50$ μC at the origin and $q_2 = -2.42$ μC at $x = 1.00$ m, find the position $x$ (between them) where the net force on a test charge $q_3$ is zero.",
    [part("", "", r"$x \approx 0.62$ m",
      r"""Between two like charges the pulls are opposite, so set the magnitudes equal: $$\frac{|q_1|}{x^2} = \frac{|q_2|}{(1.00 - x)^2} \;\Rightarrow\; \frac{1.00 - x}{x} = \sqrt{\frac{|q_2|}{|q_1|}} \;\Rightarrow\; x = \frac{1.00\ \text{m}}{1 + \sqrt{2.42/6.50}} = 0.62\ \text{m}.$$ It sits closer to the SMALLER charge $q_2$, as expected.""",
      "Balance of forces: equal magnitudes, then take square roots (choose the root that lies between the charges).")],
    nofig=True),
  P(24, r"Problem 4. Three charges are placed as shown: $q_1 = +2.00$ μC and $q_3 = +4.00$ μC; the sign and value of $q_2$ are unknown. The net force on $q_3$ is entirely in the $-x$ direction. (a) Find the magnitude of $q_2$. (b) Find the magnitude of the net force on $q_3$.",
    [part("(a)", "", r"$|q_2| = 0.843$ μC (positive)",
      r"""Only a positive $q_2$ can make the net force point along $-x$. The $y$-components must cancel: $$k\frac{|q_1|q_3}{(0.040)^2}\sin\theta_1 = k\frac{|q_2|q_3}{(0.030)^2}\sin\theta_2 \;\Rightarrow\; q_2 = \frac{9}{16}\,q_1\frac{\sin\theta_1}{\sin\theta_2} = \frac{9}{16}(2.00\ \mu\text{C})\cdot\frac34 = 0.843\ \mu\text{C}.$$""",
      "Use the given direction of the net force as an equation: zero $y$-component."),
     part("(b)", "", r"$F = 56.2$ N",
      r"""Now add the $x$-components: $$F = k q_3\left[\frac{q_1}{(0.040)^2}\cdot\frac45 + \frac{q_2}{(0.030)^2}\cdot\frac35\right] = (9\times10^9)(4.00\times10^{-6})\left[1.00\times10^{-3} + 5.62\times10^{-4}\right] = 56.2\ \text{N}.$$""",
      "With $F_y = 0$, the net force is just $F_x$.")],
    nofig=True),
])
